<?php
namespace App\Http\Controllers\App;
use App\Http\Controllers\Controller;use App\Models\Appointment;use App\Models\ConsultantProfile;use App\Models\Patient;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller { private function query(Request $request){return Appointment::query()->with(['patient','consultant.user'])->when($request->date_from,fn($q,$v)=>$q->whereDate('appointment_date','>=',$v))->when($request->date_to,fn($q,$v)=>$q->whereDate('appointment_date','<=',$v))->when($request->status,fn($q,$v)=>$q->where('status',$v))->when($request->consultant_id,fn($q,$v)=>$q->where('consultant_id',$v))->when($request->patient_id,fn($q,$v)=>$q->where('patient_id',$v))->orderByDesc('appointment_date')->orderBy('start_time');} public function appointments(Request $request){abort_unless($request->user()->hasPermission('reports.view'),403);$appointments=$this->query($request)->paginate(25)->withQueryString();$consultants=ConsultantProfile::query()->with('user')->orderBy('id')->get();$patients=Patient::query()->orderBy('last_name')->get();return view('app.reports.appointments',compact('appointments','consultants','patients'));} public function exportAppointments(Request $request):StreamedResponse{abort_unless($request->user()->hasPermission('reports.view'),403);$filename='appointment-report-'.now()->format('Y-m-d-His').'.csv';return response()->streamDownload(function()use($request){$out=fopen('php://output','w');fputcsv($out,['Date','Start','End','Status','Patient','Consultant','Notes']);$this->query($request)->chunkById(200,function($rows)use($out){foreach($rows as $a){fputcsv($out,[$a->appointment_date->format('Y-m-d'),$a->start_time,$a->end_time,$a->status->value,$a->patient->first_name.' '.$a->patient->last_name,$a->consultant->user->name,$a->notes]);}});fclose($out);},$filename,['Content-Type'=>'text/csv']);} }
